"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Activity, AlertCircle, ArrowDownToLine, ArrowLeft, ArrowRight, CalendarDays, CalendarPlus, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clapperboard, Clock3, Download, Edit3, Film, LayoutDashboard, Menu, MoreHorizontal, Plus, Search, Settings2, Store, Trash2, Video, Wallet, X } from "lucide-react";

type Status = "Agendada" | "Gravada" | "Em edição" | "Pronta para publicar" | "Publicada" | "Cancelada";
type Recording = { id: number; storeId: number; storeName: string; recordingDate: string; recordingTime: string; publicationDate: string; publicationTime: string; notes: string; status: Status; publishedAt: string | null; createdAt: string };
type Shop = { id: number; name: string; createdAt: string; paymentValue: number | null; paymentFirstDate: string | null; lastPaymentDate: string | null };
type Payment = { id: number; storeId: number; storeName: string; paidOn: string; value: number };
type Section = "painel" | "calendario" | "gravacoes" | "lojas" | "exportar";
type View = "mensal" | "semanal" | "diaria";
type Filter = "Todas as gravações" | "Gravações de hoje" | "Gravações da semana" | "Publicações de hoje" | "Publicações da semana" | "Aguardando edição" | "Prontas para publicar" | "Já publicadas" | "Canceladas";
type Form = { storeName: string; recordingDate: string; recordingTime: string; publicationDate: string; publicationTime: string; notes: string };

const statuses: Status[] = ["Agendada", "Gravada", "Em edição", "Pronta para publicar", "Publicada", "Cancelada"];
const filters: Filter[] = ["Todas as gravações", "Gravações de hoje", "Gravações da semana", "Publicações de hoje", "Publicações da semana", "Aguardando edição", "Prontas para publicar", "Já publicadas", "Canceladas"];
const weekdays = ["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"];
function todayKey() { const parts = new Intl.DateTimeFormat("en-US", { timeZone: "America/Asuncion", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date()); const get = (k: string) => parts.find(p => p.type === k)?.value || ""; return `${get("year")}-${get("month")}-${get("day")}`; }
function addDays(key: string, n: number) { const d = new Date(key + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
function weekStart(key: string) { const day = new Date(key + "T12:00:00Z").getUTCDay(); return addDays(key, -(day === 0 ? 6 : day - 1)); }
function formatDate(key: string, opts?: Intl.DateTimeFormatOptions) { return new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC", day: "2-digit", month: "short", ...opts }).format(new Date(key + "T12:00:00Z")); }
function weekday(key: string) { return new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC", weekday: "long" }).format(new Date(key + "T12:00:00Z")); }
function monthTitle(key: string) { const s = new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC", month: "long", year: "numeric" }).format(new Date(key + "T12:00:00Z")); return s.charAt(0).toUpperCase() + s.slice(1); }
function dateTime(key: string, time: string) { return `${formatDate(key, { year: "numeric" })} · ${time}`; }
function nextPaymentDate(s: Shop, nowKey: string): string | null {
  if (s.lastPaymentDate) return addDays(s.lastPaymentDate, 30);
  if (!s.paymentFirstDate) return null;
  let d = s.paymentFirstDate;
  while (d < nowKey) d = addDays(d, 30);
  return d;
}
function daysUntil(key: string, nowKey: string) { return Math.round((new Date(key + "T12:00:00Z").getTime() - new Date(nowKey + "T12:00:00Z").getTime()) / 86400000); }
function formatMoney(v: number) { return v.toLocaleString("pt-BR", { maximumFractionDigits: 2 }); }
function paymentInfo(s: Shop, nowKey: string): { text: string; cls: string } | null {
  const next = nextPaymentDate(s, nowKey);
  if (!next) return null;
  const d = daysUntil(next, nowKey);
  if (d < 0) return { text: `Vencido há ${-d} ${-d === 1 ? "dia" : "dias"}`, cls: "pay-overdue" };
  if (d === 0) return { text: "Receber hoje", cls: "pay-due" };
  if (d <= 5) return { text: `Receber em ${d} ${d === 1 ? "dia" : "dias"}`, cls: "pay-soon" };
  return { text: `Próximo: ${formatDate(next, { year: "numeric" })}`, cls: "pay-ok" };
}
function isOverdue(r: Recording, nowKey: string, currentTime: string) { return r.status !== "Publicada" && r.status !== "Cancelada" && (r.publicationDate < nowKey || (r.publicationDate === nowKey && r.publicationTime < currentTime)); }
function blankForm(today: string): Form { return { storeName: "", recordingDate: today, recordingTime: "09:00", publicationDate: addDays(today, 1), publicationTime: "18:00", notes: "" }; }
function escapeCSV(v: unknown) { return `"${String(v ?? "").replaceAll('"', '""')}"`; }
function downloadFile(content: string, name: string, mime: string) { const blob = new Blob([content], { type: mime }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); }

export default function HomePage() {
  const [section, setSection] = useState<Section>("painel");
  const [records, setRecords] = useState<Recording[]>([]);
  const [shops, setShops] = useState<Shop[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState("");
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<Filter>("Todas as gravações");
  const [view, setView] = useState<View>("mensal");
  const [selectedDate, setSelectedDate] = useState(todayKey);
  const [cursor, setCursor] = useState(todayKey);
  const [selectedRecord, setSelectedRecord] = useState<Recording | null>(null);
  const [formOpen, setFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [form, setForm] = useState<Form>(() => blankForm(todayKey()));
  const [formError, setFormError] = useState("");
  const [storeOpen, setStoreOpen] = useState(false);
  const [storeName, setStoreName] = useState("");
  const [storeValue, setStoreValue] = useState("");
  const [storeFirstDate, setStoreFirstDate] = useState("");
  const [storeError, setStoreError] = useState("");
  const [storeTab, setStoreTab] = useState<"recebimentos" | "videos">("recebimentos");
  const [payModal, setPayModal] = useState<null | { mode: "register" | "edit"; shop: Shop }>(null);
  const [payDate, setPayDate] = useState("");
  const [payValue, setPayValue] = useState("");
  const [payError, setPayError] = useState("");
  const [activeStore, setActiveStore] = useState<Shop | null>(null);
  const [mobileNav, setMobileNav] = useState(false);
  const [timeNow, setTimeNow] = useState(() => new Intl.DateTimeFormat("en-GB", { timeZone: "America/Asuncion", hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date()));
  const today = todayKey();
  const tomorrow = addDays(today, 1);

  const refresh = useCallback(async () => { try { const response = await fetch("/api/data", { cache: "no-store" }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Erro ao carregar dados."); setRecords(data.recordings); setShops(data.stores); setPayments(data.payments ?? []); } catch (e) { setToast(e instanceof Error ? e.message : "Erro ao carregar dados."); } finally { setLoading(false); } }, []);
  useEffect(() => { refresh(); const timer = setInterval(() => { setTimeNow(new Intl.DateTimeFormat("en-GB", { timeZone: "America/Asuncion", hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date())); }, 60000); return () => clearInterval(timer); }, [refresh]);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(""), 4500); return () => clearTimeout(t); }, [toast]);
  useEffect(() => { const handler = (event: KeyboardEvent) => { if (event.key === "Escape") { setFormOpen(false); setStoreOpen(false); setSelectedRecord(null); setActiveStore(null); } }; document.addEventListener("keydown", handler); return () => document.removeEventListener("keydown", handler); }, []);

  const upcomingRecordings = useMemo(() => records.filter(r => r.status !== "Cancelada" && r.recordingDate >= today && ["Agendada"].includes(r.status)).sort((a,b) => (a.recordingDate + a.recordingTime).localeCompare(b.recordingDate + b.recordingTime)), [records, today]);
  const upcomingPublications = useMemo(() => records.filter(r => r.status !== "Cancelada" && r.status !== "Publicada").sort((a,b) => (a.publicationDate + a.publicationTime).localeCompare(b.publicationDate + b.publicationTime)), [records]);
  const overdue = upcomingPublications.filter(r => isOverdue(r, today, timeNow));
  const dueSoon = upcomingRecordings.filter(r => r.recordingDate === today).length + upcomingPublications.filter(r => r.publicationDate === today).length;
  const upcomingPayments = shops.map(s => { const next = nextPaymentDate(s, today); return next ? { shop: s, next, days: daysUntil(next, today) } : null; }).filter((x): x is { shop: Shop; next: string; days: number } => x !== null && x.days <= 5).sort((a, b) => a.days - b.days);
  const stats = [
    { label: "Gravações hoje", value: records.filter(r => r.recordingDate === today && r.status === "Agendada").length, icon: Video, kind: "blue", foot: "agendadas para hoje" },
    { label: "Publicações hoje", value: records.filter(r => r.publicationDate === today && !["Publicada", "Cancelada"].includes(r.status)).length, icon: CalendarDays, kind: "green", foot: "previstas para hoje" },
    { label: "Aguardando edição", value: records.filter(r => ["Gravada", "Em edição"].includes(r.status)).length, icon: Film, kind: "amber", foot: "vídeos em andamento" },
    { label: "Publicados no mês", value: records.filter(r => r.status === "Publicada" && r.publishedAt && new Intl.DateTimeFormat("en-CA", { timeZone: "America/Asuncion", year: "numeric", month: "2-digit" }).format(new Date(r.publishedAt)) === today.slice(0, 7)).length, icon: CheckCircle2, kind: "purple", foot: "publicados este mês" },
  ];

  const filtered = useMemo(() => records.filter(r => {
    if (!r.storeName.toLocaleLowerCase("pt-BR").includes(search.toLocaleLowerCase("pt-BR").trim())) return false;
    const end = addDays(weekStart(today), 6);
    switch (filter) {
      case "Gravações de hoje": return r.recordingDate === today && r.status !== "Cancelada";
      case "Gravações da semana": return r.recordingDate >= weekStart(today) && r.recordingDate <= end && r.status !== "Cancelada";
      case "Publicações de hoje": return r.publicationDate === today && r.status !== "Cancelada";
      case "Publicações da semana": return r.publicationDate >= weekStart(today) && r.publicationDate <= end && r.status !== "Cancelada";
      case "Aguardando edição": return ["Gravada", "Em edição"].includes(r.status);
      case "Prontas para publicar": return r.status === "Pronta para publicar";
      case "Já publicadas": return r.status === "Publicada";
      case "Canceladas": return r.status === "Cancelada";
      default: return true;
    }
  }).sort((a,b) => (b.recordingDate + b.recordingTime).localeCompare(a.recordingDate + a.recordingTime)), [records, search, filter, today]);

  function openNew(date?: string) { setEditingId(null); setForm(blankForm(date || today)); setFormError(""); setSelectedRecord(null); setActiveStore(null); setFormOpen(true); }
  function openEdit(r: Recording) { setEditingId(r.id); setForm({ storeName: r.storeName, recordingDate: r.recordingDate, recordingTime: r.recordingTime, publicationDate: r.publicationDate, publicationTime: r.publicationTime, notes: r.notes }); setFormError(""); setSelectedRecord(null); setFormOpen(true); }
  function updateRecordingDate(value: string) { setForm(f => ({ ...f, recordingDate: value, publicationDate: value ? addDays(value, 1) : "" })); }
  const localConflict = records.find(r => r.id !== editingId && r.status !== "Cancelada" && r.recordingDate === form.recordingDate && r.recordingTime === form.recordingTime);

  async function saveRecording(e: React.FormEvent) {
    e.preventDefault(); setFormError("");
    if (localConflict) { setFormError(`Conflito: ${localConflict.storeName} já tem gravação neste dia e horário.`); return; }
    setBusy(true);
    try { const response = await fetch("/api/data", { method: editingId ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type: "recording", id: editingId, ...form }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Não foi possível salvar."); setFormOpen(false); setToast(editingId ? "Gravação atualizada com sucesso." : "Gravação agendada com sucesso."); await refresh(); } catch (e) { setFormError(e instanceof Error ? e.message : "Erro ao salvar."); } finally { setBusy(false); }
  }
  function openStoreModal() { setStoreName(""); setStoreValue(""); setStoreFirstDate(""); setStoreError(""); setStoreOpen(true); }
  async function saveStore(e: React.FormEvent) { e.preventDefault(); setStoreError(""); setBusy(true); try { const response = await fetch("/api/data", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type: "store", name: storeName, paymentValue: storeValue, paymentFirstDate: storeFirstDate || null }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Não foi possível cadastrar."); setStoreOpen(false); setToast("Loja cadastrada com sucesso."); await refresh(); } catch (e) { setStoreError(e instanceof Error ? e.message : "Erro ao cadastrar."); } finally { setBusy(false); } }
  function openPayModal(mode: "register" | "edit", shop: Shop) { const next = nextPaymentDate(shop, today); setPayModal({ mode, shop }); setPayDate(mode === "register" ? (next ?? today) : (shop.paymentFirstDate ?? "")); setPayValue(shop.paymentValue !== null ? String(shop.paymentValue) : (mode === "register" ? "" : "")); setPayError(""); }
  async function savePayModal(e: React.FormEvent) { e.preventDefault(); if (!payModal) return; setPayError(""); setBusy(true); const isRegister = payModal.mode === "register"; try { const response = await fetch("/api/data", { method: isRegister ? "POST" : "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(isRegister ? { type: "payment", storeId: payModal.shop.id, paidOn: payDate, value: payValue } : { type: "store", id: payModal.shop.id, paymentValue: payValue, paymentFirstDate: payDate || null }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Não foi possível salvar."); setPayModal(null); setToast(isRegister ? "Recebimento registrado. Próxima cobrança em 30 dias." : "Informações do recebimento atualizadas."); await refresh(); } catch (e) { setPayError(e instanceof Error ? e.message : "Erro ao salvar."); } finally { setBusy(false); } }
  async function resetCycle() { if (!payModal) return; if (!window.confirm("Reiniciar a contagem a partir da data inicial desta loja?")) return; setBusy(true); try { const response = await fetch("/api/data", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type: "store", id: payModal.shop.id, resetCycle: true }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Não foi possível reiniciar."); setPayModal(null); setToast("Ciclo reiniciado a partir da data inicial."); await refresh(); } catch (e) { setPayError(e instanceof Error ? e.message : "Erro ao reiniciar."); } finally { setBusy(false); } }
  async function changeStatus(r: Recording, status: Status) { setBusy(true); try { const response = await fetch("/api/data", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type: "status", id: r.id, status }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Não foi possível alterar o status."); setSelectedRecord(null); setToast(status === "Publicada" ? "Publicado! Data efetiva registrada." : `Status alterado para ${status}.`); await refresh(); } catch (e) { setToast(e instanceof Error ? e.message : "Erro ao alterar status."); } finally { setBusy(false); } }
  async function deleteRecording(r: Recording) { if (!window.confirm(`Excluir definitivamente a gravação de ${r.storeName}?`)) return; setBusy(true); try { const response = await fetch(`/api/data?id=${r.id}`, { method: "DELETE" }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Não foi possível excluir."); setSelectedRecord(null); setToast("Gravação excluída."); await refresh(); } catch (e) { setToast(e instanceof Error ? e.message : "Erro ao excluir."); } finally { setBusy(false); } }
  function exportCSV(kind: "gravacoes" | "publicacoes" | "historico") { const headers = ["Tipo", "Loja", "Data gravação", "Hora gravação", "Data publicação prevista", "Hora publicação prevista", "Status", "Publicado em", "Observações"]; const rows = records.flatMap(r => (kind === "historico" ? ["Gravação", "Publicação"] : [kind === "gravacoes" ? "Gravação" : "Publicação"]).map(type => [type, r.storeName, r.recordingDate, r.recordingTime, r.publicationDate, r.publicationTime, r.status, r.publishedAt ? new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Asuncion", dateStyle: "short", timeStyle: "short" }).format(new Date(r.publishedAt)) : "", r.notes])); downloadFile("\uFEFF" + [headers, ...rows].map(row => row.map(escapeCSV).join(";")).join("\r\n"), `imigra-${kind}-${today}.csv`, "text/csv;charset=utf-8"); setToast("Arquivo CSV exportado."); }
  function backup() { downloadFile(JSON.stringify({ app: "Agenda do Imigra", exportedAt: new Date().toISOString(), stores: shops, recordings: records }, null, 2), `imigra-backup-${today}.json`, "application/json"); setToast("Backup baixado com sucesso."); }
  function goTo(s: Section) { setSection(s); setMobileNav(false); setActiveStore(null); }
  const nav = [{ id: "painel" as Section, label: "Painel inicial", icon: LayoutDashboard }, { id: "calendario" as Section, label: "Calendário", icon: CalendarDays }, { id: "gravacoes" as Section, label: "Gravações", icon: Clapperboard }, { id: "lojas" as Section, label: "Minhas lojas", icon: Store }, { id: "exportar" as Section, label: "Exportar e backup", icon: ArrowDownToLine }];
  const dayEvents = (key: string) => records.flatMap(r => { const a: { record: Recording; type: "recording" | "publication"; time: string }[] = []; if (r.recordingDate === key) a.push({ record: r, type: "recording", time: r.recordingTime }); if (r.publicationDate === key) a.push({ record: r, type: "publication", time: r.publicationTime }); return a; }).sort((a,b) => a.time.localeCompare(b.time));
  const eventClass = (r: Recording, type: "recording" | "publication") => r.status === "Cancelada" ? "cancelled" : type === "publication" && isOverdue(r, today, timeNow) ? "late" : type === "publication" ? "publication" : "recording";
  const calendarStart = weekStart(cursor.slice(0, 7) + "-01");
  const calendarDays = Array.from({ length: 42 }, (_, i) => addDays(calendarStart, i));
  const weekDays = Array.from({ length: 7 }, (_, i) => addDays(weekStart(cursor), i));
  function moveCalendar(direction: number) { if (view === "mensal") { const d = new Date(cursor + "T12:00:00Z"); d.setUTCMonth(d.getUTCMonth() + direction); setCursor(d.toISOString().slice(0, 10)); } else setCursor(addDays(cursor, direction * (view === "semanal" ? 7 : 1))); }

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? "sidebar-open" : ""}`}>
      <div className="brand"><div className="brand-mark"><Clapperboard size={24} strokeWidth={2.4} /></div><div><strong>AGENDA DO<br /><span>IMIGRA</span></strong><small>Seu conteúdo, no tempo certo.</small></div></div>
      <div className="side-caption">MENU PRINCIPAL</div>
      <nav className="side-nav">{nav.map(item => <button key={item.id} onClick={() => goTo(item.id)} className={`nav-item ${section === item.id ? "active" : ""}`}><item.icon size={19} strokeWidth={1.9} /><span>{item.label}</span>{section === item.id && <span className="nav-active-dot" />}</button>)}</nav>
      <div className="sidebar-spacer" />
      <div className="side-action"><div className="side-action-icon"><CalendarPlus size={21} /></div><strong>Próxima gravação?</strong><p>Organize uma nova visita à loja em poucos segundos.</p><button onClick={() => { openNew(); setMobileNav(false); }}>Nova gravação <ArrowRight size={16} /></button></div>
      <div className="side-footer"><div className="online-dot" /> Dados salvos online <span>v1.0</span></div>
    </aside>
    {mobileNav && <button className="mobile-scrim" onClick={() => setMobileNav(false)} aria-label="Fechar menu" />}
    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="mobile-menu" onClick={() => setMobileNav(true)} aria-label="Abrir menu"><Menu size={22} /></button><span className="breadcrumb">Agenda do Imigra</span><ChevronRight size={15} className="breadcrumb-chevron" /><strong>{nav.find(n => n.id === section)?.label}</strong></div><div className="topbar-right"><span className="today-pill"><CalendarDays size={15} /> {formatDate(today, { year: "numeric", weekday: "short" })}</span><span className="avatar">I</span></div></header>
      <div className="content-wrap">
      {section === "painel" && <>
        <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line" /> SUA ROTINA EM UM LUGAR</div><h1>Bom dia, Imigra <span className="wave">✳</span></h1><p>Veja o que precisa de você hoje e mantenha tudo em dia.</p></div><button className="primary-btn heading-btn" onClick={() => openNew()}><Plus size={20} /> Nova gravação</button></div>
        <section className="hero-card"><div className="hero-content"><span className="hero-kicker"><span className="hero-kicker-dot" /> VISÃO DO DIA</span><h2>Seu dia, sob controle.</h2><p>{dueSoon ? `Você tem ${dueSoon} ${dueSoon === 1 ? "compromisso" : "compromissos"} para hoje. Confira sua agenda e siga o plano!` : "Tudo organizado por aqui. Que tal planejar sua próxima gravação?"}</p><button onClick={() => { goTo("calendario"); setCursor(today); setSelectedDate(today); setView("diaria"); }}>Ver calendário <ArrowRight size={17} /></button></div><div className="hero-art" aria-hidden="true"><div className="art-orbit orbit-one" /><div className="art-orbit orbit-two" /><div className="art-card art-card-back"><span className="art-mini-circle" /><span className="art-mini-line" /><span className="art-mini-line short" /></div><div className="art-card art-card-front"><div className="art-top"><span /><span /><span /></div><div className="art-big">{new Date(today + "T12:00:00Z").getUTCDate()}</div><div className="art-small">{new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC", month: "long" }).format(new Date(today + "T12:00:00Z"))}</div><div className="art-bars"><i /><i /><i /></div></div><div className="art-check"><Check size={26} strokeWidth={3} /></div></div></section>
        <div className="section-label-row"><div><h2>Visão geral</h2><p>Seu trabalho em números, atualizado em tempo real.</p></div><span className="live-label"><span /> AO VIVO</span></div>
        <div className="stats-grid">{stats.map(s => <div className="stat-card" key={s.label}><div className={`stat-icon ${s.kind}`}><s.icon size={23} strokeWidth={2} /></div><div className="stat-number">{loading ? "—" : s.value}</div><div className="stat-label">{s.label}</div><div className="stat-foot">{s.foot}</div></div>)}</div>
        {(overdue.length > 0 || dueSoon > 0) && <div className={`notice ${overdue.length ? "notice-danger" : "notice-info"}`}><div className="notice-icon"><AlertCircle size={20} /></div><div><strong>{overdue.length ? `${overdue.length} ${overdue.length === 1 ? "publicação atrasada" : "publicações atrasadas"}` : `${dueSoon} ${dueSoon === 1 ? "compromisso" : "compromissos"} para hoje`}</strong><p>{overdue.length ? "Confira os vídeos pendentes e atualize o status quando publicar." : "Não esqueça de conferir os horários programados para hoje."}</p></div><button onClick={() => goTo(overdue.length ? "gravacoes" : "calendario")}>Ver detalhes <ArrowRight size={15} /></button></div>}
        {upcomingPayments.length > 0 && <div className="notice notice-warning"><div className="notice-icon"><Wallet size={20} /></div><div><strong>{upcomingPayments.length} {upcomingPayments.length === 1 ? "recebimento" : "recebimentos"} em até 5 dias</strong><p>{upcomingPayments.slice(0, 3).map(p => `${p.shop.name} — ${p.days < 0 ? `vencido há ${-p.days} ${-p.days === 1 ? "dia" : "dias"}` : p.days === 0 ? "hoje" : `em ${p.days} ${p.days === 1 ? "dia" : "dias"}`}${p.shop.paymentValue !== null ? ` (${formatMoney(p.shop.paymentValue)})` : ""}`).join(" · ")}{upcomingPayments.length > 3 ? ` e mais ${upcomingPayments.length - 3}` : ""}.</p></div><button onClick={() => goTo("lojas")}>Ver lojas <ArrowRight size={15} /></button></div>}
        <div className="lists-grid"><section className="panel list-panel"><div className="panel-header"><div className="panel-title"><div className="panel-icon blue"><Video size={19} /></div><div><h2>Gravações próximas</h2><p>Próximas visitas agendadas</p></div></div><button className="text-link" onClick={() => { setFilter("Todas as gravações"); goTo("gravacoes"); }}>Ver todas <ArrowRight size={15} /></button></div><div className="panel-body">{loading ? <div className="empty-small">Carregando...</div> : upcomingRecordings.length ? upcomingRecordings.slice(0, 5).map(r => <button className="list-row" key={r.id} onClick={() => setSelectedRecord(r)}><div className="row-icon blue"><Video size={18} /></div><div className="row-main"><strong>{r.storeName}</strong><span><CalendarDays size={13} /> {dateTime(r.recordingDate, r.recordingTime)}</span></div><span className="status-badge scheduled">{r.status}</span><ChevronRight className="row-chevron" size={17} /></button>) : <EmptyState icon={Video} title="Nenhuma gravação próxima" text="Suas próximas visitas aparecerão aqui." action="Agendar gravação" onClick={() => openNew()} />}</div></section>
        <section className="panel list-panel"><div className="panel-header"><div className="panel-title"><div className="panel-icon green"><CalendarDays size={19} /></div><div><h2>Publicações próximas</h2><p>O que vai ao ar em breve</p></div></div><button className="text-link" onClick={() => { setFilter("Publicações da semana"); goTo("gravacoes"); }}>Ver todas <ArrowRight size={15} /></button></div><div className="panel-body">{loading ? <div className="empty-small">Carregando...</div> : upcomingPublications.length ? upcomingPublications.slice(0, 5).map(r => <button className="list-row" key={r.id} onClick={() => setSelectedRecord(r)}><div className={`row-icon ${isOverdue(r, today, timeNow) ? "red" : "green"}`}><CalendarDays size={18} /></div><div className="row-main"><strong>{r.storeName}</strong><span><Clock3 size={13} /> {dateTime(r.publicationDate, r.publicationTime)}</span></div><span className={`status-badge ${isOverdue(r, today, timeNow) ? "overdue" : "upcoming"}`}>{isOverdue(r, today, timeNow) ? "Atrasada" : r.publicationDate === today ? "Hoje" : r.publicationDate === tomorrow ? "Amanhã" : "Prevista"}</span><ChevronRight className="row-chevron" size={17} /></button>) : <EmptyState icon={CalendarDays} title="Nenhuma publicação pendente" text="Suas publicações planejadas aparecerão aqui." />}</div></section></div>
      </>}

      {section === "calendario" && <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line" /> PLANEJAMENTO</div><h1>Calendário</h1><p>Gravações e publicações, tudo no seu tempo.</p></div><button className="primary-btn heading-btn" onClick={() => openNew(selectedDate)}><Plus size={20} /> Nova gravação</button></div><div className="calendar-shell panel"><div className="calendar-toolbar"><div className="calendar-controls"><h2>{view === "mensal" ? monthTitle(cursor) : view === "semanal" ? `${formatDate(weekDays[0])} – ${formatDate(weekDays[6], { year: "numeric" })}` : `${weekday(cursor)}, ${formatDate(cursor, { year: "numeric" })}`}</h2><div className="calendar-arrows"><button onClick={() => moveCalendar(-1)} aria-label="Anterior"><ChevronLeft size={19} /></button><button onClick={() => { setCursor(today); setSelectedDate(today); }}>Hoje</button><button onClick={() => moveCalendar(1)} aria-label="Próximo"><ChevronRight size={19} /></button></div></div><div className="view-switch">{(["mensal", "semanal", "diaria"] as View[]).map(v => <button key={v} className={view === v ? "active" : ""} onClick={() => setView(v)}>{v === "diaria" ? "Diária" : v === "semanal" ? "Semanal" : "Mensal"}</button>)}</div></div><div className="calendar-legend"><span><i className="legend-dot blue" /> Gravação</span><span><i className="legend-dot green" /> Publicação</span><span><i className="legend-dot red" /> Atrasada</span><span><i className="legend-dot gray" /> Cancelada</span></div>
      {view === "mensal" && <div className="month-calendar"><div className="weekday-header">{weekdays.map(w => <div key={w}>{w}</div>)}</div><div className="month-grid">{calendarDays.map(key => { const events = dayEvents(key); return <button key={key} className={`calendar-cell ${key.slice(0,7) !== cursor.slice(0,7) ? "other-month" : ""} ${key === selectedDate ? "selected" : ""}`} onClick={() => setSelectedDate(key)}><span className={`cell-date ${key === today ? "today" : ""}`}>{Number(key.slice(-2))}</span><div className="cell-events">{events.slice(0, 3).map((ev, i) => <span key={`${ev.record.id}-${ev.type}-${i}`} className={`mini-event ${eventClass(ev.record, ev.type)}`} title={`${ev.time} ${ev.record.storeName} — abrir detalhes`} onClick={e => { e.stopPropagation(); setSelectedRecord(ev.record); }}><span className="mini-event-dot" />{ev.time} {ev.record.storeName}</span>)}{events.length > 3 && <span className="more-events">+{events.length - 3} mais</span>}</div></button>; })}</div></div>}
      {view === "semanal" && <div className="week-calendar">{weekDays.map(key => <button key={key} className={`week-day ${key === selectedDate ? "selected" : ""}`} onClick={() => setSelectedDate(key)}><div className="week-day-heading"><span>{weekday(key)}</span><strong className={key === today ? "today" : ""}>{Number(key.slice(-2))}</strong></div><div className="week-events">{dayEvents(key).map(ev => <div key={`${ev.record.id}-${ev.type}`} className={`week-event ${eventClass(ev.record, ev.type)}`} onClick={e => { e.stopPropagation(); setSelectedRecord(ev.record); }}><small>{ev.time}</small><strong>{ev.record.storeName}</strong><span>{ev.type === "recording" ? "Gravação" : "Publicação"}</span></div>)}{dayEvents(key).length === 0 && <span className="week-empty">Sem eventos</span>}</div></button>)}</div>}
      {view === "diaria" && <div className="day-calendar"><div className="day-heading"><span className="day-number">{Number(cursor.slice(-2))}</span><div><strong>{weekday(cursor)}</strong><span>{formatDate(cursor, { month: "long", year: "numeric" })}</span></div></div>{dayEvents(cursor).length ? dayEvents(cursor).map(ev => <button className="day-event-row" key={`${ev.record.id}-${ev.type}`} onClick={() => setSelectedRecord(ev.record)}><span className="event-time">{ev.time}</span><span className={`event-stripe ${eventClass(ev.record, ev.type)}`} /><span className="event-info"><strong>{ev.record.storeName}</strong><small>{ev.type === "recording" ? "Gravação" : "Publicação"} · {ev.record.status}</small></span><ChevronRight size={17} /></button>) : <EmptyState icon={CalendarDays} title="Dia livre na agenda" text="Nenhum compromisso marcado para esta data." action="Adicionar gravação" onClick={() => openNew(cursor)} />}</div>}
      </div>{view !== "diaria" && <section className="panel selected-day-panel"><div className="panel-header"><div className="panel-title"><div className="panel-icon blue"><CalendarDays size={19} /></div><div><h2>{selectedDate === today ? "Hoje" : `${weekday(selectedDate).replace(/^./, c => c.toUpperCase())}, ${formatDate(selectedDate, { year: "numeric" })}`}</h2><p>{dayEvents(selectedDate).length} {dayEvents(selectedDate).length === 1 ? "compromisso" : "compromissos"} neste dia</p></div></div><button className="text-link" onClick={() => openNew(selectedDate)}><Plus size={16} /> Adicionar</button></div><div className="selected-day-list">{dayEvents(selectedDate).length ? dayEvents(selectedDate).map(ev => <button key={`${ev.record.id}-${ev.type}`} className="selected-event" onClick={() => setSelectedRecord(ev.record)}><span className={`event-type-icon ${eventClass(ev.record, ev.type)}`}>{ev.type === "recording" ? <Video size={17} /> : <CalendarDays size={17} />}</span><span><strong>{ev.record.storeName}</strong><small>{ev.type === "recording" ? "Gravação" : "Publicação"} · {ev.time}</small></span><span className={`status-badge ${statusClass(ev.record.status)}`}>{ev.record.status}</span><ChevronRight size={17} /></button>) : <div className="empty-small">Nenhum compromisso nesta data.</div>}</div></section>}</>}

      {section === "gravacoes" && <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line" /> TODOS OS COMPROMISSOS</div><h1>Gravações</h1><p>Gerencie seus vídeos do agendamento até a publicação.</p></div><button className="primary-btn heading-btn" onClick={() => openNew()}><Plus size={20} /> Nova gravação</button></div><div className="panel records-panel"><div className="records-controls"><div className="search-box"><Search size={19} /><input placeholder="Buscar por nome da loja..." value={search} onChange={e => setSearch(e.target.value)} aria-label="Buscar loja" />{search && <button onClick={() => setSearch("")} aria-label="Limpar busca"><X size={16} /></button>}</div><div className="filter-box"><Settings2 size={17} /><select value={filter} onChange={e => setFilter(e.target.value as Filter)} aria-label="Filtrar gravações">{filters.map(f => <option key={f}>{f}</option>)}</select><ChevronDown size={15} /></div></div><div className="records-count">{filtered.length} {filtered.length === 1 ? "registro encontrado" : "registros encontrados"}</div><div className="records-table-wrap"><table className="records-table"><thead><tr><th>LOJA</th><th>GRAVAÇÃO</th><th>PUBLICAÇÃO</th><th>STATUS</th><th></th></tr></thead><tbody>{filtered.map(r => <tr key={r.id} onClick={() => setSelectedRecord(r)}><td><span className="table-store-icon"><Store size={17} /></span><strong>{r.storeName}</strong></td><td>{formatDate(r.recordingDate, { year: "numeric" })}<small>{r.recordingTime}</small></td><td>{formatDate(r.publicationDate, { year: "numeric" })}<small>{r.publicationTime} {isOverdue(r, today, timeNow) && <em>· Atrasada</em>}</small></td><td><span className={`status-badge ${isOverdue(r, today, timeNow) ? "overdue" : statusClass(r.status)}`}>{isOverdue(r, today, timeNow) ? "Atrasada" : r.status}</span></td><td><button className="icon-button" onClick={e => { e.stopPropagation(); setSelectedRecord(r); }} aria-label="Ver detalhes"><MoreHorizontal size={20} /></button></td></tr>)}</tbody></table>{!loading && !filtered.length && <EmptyState icon={Clapperboard} title={search || filter !== "Todas as gravações" ? "Nenhum resultado encontrado" : "Sua agenda começa aqui"} text={search || filter !== "Todas as gravações" ? "Tente buscar por outro nome ou alterar o filtro." : "Adicione sua primeira gravação para começar."} action={!search && filter === "Todas as gravações" ? "Nova gravação" : undefined} onClick={() => openNew()} />}</div></div></>}

      {section === "lojas" && <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line" /> SEUS PARCEIROS</div><h1>Minhas lojas</h1><p>Um lugar para acompanhar cada parceria e seu histórico.</p></div><button className="primary-btn heading-btn" onClick={openStoreModal}><Plus size={20} /> Nova loja</button></div><div className="shop-summary"><div className="shop-summary-icon"><Store size={24} /></div><div><strong>{shops.length}</strong><span>{shops.length === 1 ? "loja cadastrada" : "lojas cadastradas"}</span></div><div className="shop-summary-divider" /><div><strong>{records.length}</strong><span>{records.length === 1 ? "vídeo na agenda" : "vídeos na agenda"}</span></div></div>{shops.length ? <div className="stores-grid">{shops.map(s => { const related = records.filter(r => r.storeId === s.id); return <button className="store-card" key={s.id} onClick={() => { setActiveStore(s); setStoreTab("recebimentos"); }}><div className="store-card-top"><div className="store-avatar">{s.name.charAt(0).toUpperCase()}</div><ArrowRight size={18} /></div><h3>{s.name}</h3><p>{related.length} {related.length === 1 ? "vídeo" : "vídeos"} na agenda</p>{(() => { const info = paymentInfo(s, today); return info ? <div className={`store-pay-badge ${info.cls}`}><Wallet size={15} /><span>{info.text}</span><strong>{formatMoney(s.paymentValue ?? 0)}</strong></div> : null; })()}<div className="store-card-bottom"><span><Video size={15} /> {related.filter(r => r.status !== "Cancelada").length} gravações</span><span><CheckCircle2 size={15} /> {related.filter(r => r.status === "Publicada").length} publicados</span></div></button>; })}</div> : !loading && <div className="panel"><EmptyState icon={Store} title="Nenhuma loja cadastrada" text="Cadastre uma loja para acompanhar seus vídeos. Você também pode cadastrá-la ao criar uma gravação." action="Cadastrar loja" onClick={() => { setStoreError(""); setStoreOpen(true); }} /></div>}</>}

      {section === "exportar" && <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line" /> SEUS DADOS</div><h1>Exportar e backup</h1><p>Seus registros são seus. Baixe uma cópia sempre que quiser.</p></div></div><div className="export-intro"><div className="export-intro-icon"><ArrowDownToLine size={26} /></div><div><h2>Tudo pronto para baixar</h2><p>Exporte planilhas CSV para organizar seu trabalho ou salve um backup completo em JSON.</p></div></div><div className="export-grid"><div className="export-card"><div className="export-icon blue"><Video size={23} /></div><h3>Todas as gravações</h3><p>Datas, horários, lojas e status de todas as suas gravações.</p><button onClick={() => exportCSV("gravacoes")}>Baixar CSV <ArrowDownToLine size={17} /></button></div><div className="export-card"><div className="export-icon green"><CalendarDays size={23} /></div><h3>Todas as publicações</h3><p>Planejamento e datas efetivas das publicações dos seus vídeos.</p><button onClick={() => exportCSV("publicacoes")}>Baixar CSV <ArrowDownToLine size={17} /></button></div><div className="export-card"><div className="export-icon purple"><Activity size={23} /></div><h3>Histórico completo</h3><p>Uma linha para cada gravação e publicação em um único arquivo.</p><button onClick={() => exportCSV("historico")}>Baixar CSV <ArrowDownToLine size={17} /></button></div><div className="export-card"><div className="export-icon blue"><Download size={23} /></div><h3>Código do aplicativo</h3><p>Baixe um ZIP com todos os arquivos do app para publicar no Render ou enviar para quem ajuda com a publicação.</p><button onClick={() => { window.location.href = "/api/download-app"; }}><Download size={17} /> Baixar ZIP</button></div></div><div className="backup-card"><div className="backup-graphic"><div><Check size={29} /></div></div><div><h3>Faça um backup dos seus dados</h3><p>Baixe um arquivo JSON com todas as lojas e gravações para guardar com segurança.</p></div><button onClick={backup}>Baixar backup <ArrowDownToLine size={17} /></button></div><div className="export-note"><CircleHelp size={18} /> Os dados são salvos no banco de dados do aplicativo. Os arquivos baixados são cópias extras para sua segurança.</div></>}
      </div>
    </main>

    {formOpen && <div className="modal-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setFormOpen(false); }}><div className="modal form-modal" role="dialog" aria-modal="true" aria-label={editingId ? "Editar gravação" : "Nova gravação"}><div className="modal-head"><div><span className="modal-eyebrow">{editingId ? "ATUALIZAR COMPROMISSO" : "NOVO COMPROMISSO"}</span><h2>{editingId ? "Editar gravação" : "Nova gravação"}</h2><p>Preencha os detalhes para organizar sua agenda.</p></div><button className="close-btn" onClick={() => setFormOpen(false)} aria-label="Fechar"><X size={21} /></button></div><form onSubmit={saveRecording}><div className="modal-content"><label className="field full"><span>Nome da loja <b>*</b></span><div className="input-with-icon"><Store size={18} /><input required maxLength={160} placeholder="Ex: Shopping China" list="store-suggestions" value={form.storeName} onChange={e => setForm(f => ({ ...f, storeName: e.target.value }))} /></div><datalist id="store-suggestions">{shops.map(s => <option value={s.name} key={s.id} />)}</datalist><small>Selecione uma loja cadastrada ou digite uma nova.</small></label><div className="form-section-label"><span className="form-section-icon blue"><Video size={17} /></span> Gravação</div><div className="form-grid"><label className="field"><span>Data da gravação <b>*</b></span><input required type="date" value={form.recordingDate} onChange={e => updateRecordingDate(e.target.value)} /></label><label className="field"><span>Horário <b>*</b></span><input required type="time" value={form.recordingTime} onChange={e => setForm(f => ({ ...f, recordingTime: e.target.value }))} /></label></div>{localConflict && <div className="inline-error"><AlertCircle size={16} /> Já existe uma gravação de {localConflict.storeName} neste horário. Escolha outro.</div>}<div className="form-section-label publication-title"><span className="form-section-icon green"><CalendarDays size={17} /></span> Publicação <span className="auto-tag">+1 dia automático</span></div><div className="form-grid"><label className="field"><span>Data da publicação <b>*</b></span><input required type="date" value={form.publicationDate} onChange={e => setForm(f => ({ ...f, publicationDate: e.target.value }))} /></label><label className="field"><span>Horário <b>*</b></span><input required type="time" value={form.publicationTime} onChange={e => setForm(f => ({ ...f, publicationTime: e.target.value }))} /></label></div><label className="field full notes-field"><span>Observações <i>(opcional)</i></span><textarea rows={3} maxLength={2000} placeholder="Detalhes sobre a visita ou o conteúdo..." value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} /></label>{formError && <div className="inline-error"><AlertCircle size={17} /> {formError}</div>}</div><div className="modal-footer"><button type="button" className="secondary-btn" onClick={() => setFormOpen(false)}>Cancelar</button><button className="primary-btn" disabled={busy || !!localConflict} type="submit"><Check size={18} /> {busy ? "Salvando..." : editingId ? "Salvar alterações" : "Agendar gravação"}</button></div></form></div></div>}
    {storeOpen && <div className="modal-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setStoreOpen(false); }}><div className="modal small-modal" role="dialog" aria-modal="true" aria-label="Nova loja"><div className="modal-head"><div><span className="modal-eyebrow">SEUS PARCEIROS</span><h2>Nova loja</h2><p>Cadastre sua parceria, o valor mensal e a data do recebimento.</p></div><button className="close-btn" onClick={() => setStoreOpen(false)} aria-label="Fechar"><X size={21} /></button></div><form onSubmit={saveStore}><div className="modal-content"><label className="field full"><span>Nome da loja <b>*</b></span><div className="input-with-icon"><Store size={18} /><input required maxLength={160} autoFocus placeholder="Nome da loja" value={storeName} onChange={e => setStoreName(e.target.value)} /></div></label><div className="form-section-label"><span className="form-section-icon green"><Wallet size={17} /></span> Recebimento mensal <span className="auto-tag">opcional</span></div><div className="form-grid"><label className="field"><span>Valor combinado</span><input type="text" inputMode="decimal" placeholder="Ex: 300,00" value={storeValue} onChange={e => setStoreValue(e.target.value)} /></label><label className="field"><span>Primeiro recebimento</span><input type="date" value={storeFirstDate} onChange={e => setStoreFirstDate(e.target.value)} /></label></div><p className="field-hint">O ciclo se repete a cada 30 dias e você será avisado com 5 dias de antecedência.</p>{storeError && <div className="inline-error"><AlertCircle size={17} /> {storeError}</div>}</div><div className="modal-footer"><button type="button" className="secondary-btn" onClick={() => setStoreOpen(false)}>Cancelar</button><button className="primary-btn" disabled={busy} type="submit"><Plus size={18} /> {busy ? "Salvando..." : "Cadastrar loja"}</button></div></form></div></div>}
    {selectedRecord && <div className="modal-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setSelectedRecord(null); }}><div className="modal detail-modal" role="dialog" aria-modal="true" aria-label="Detalhes da gravação"><div className="modal-head"><div><span className="modal-eyebrow">DETALHES DO VÍDEO</span><h2>{selectedRecord.storeName}</h2><p>Gerencie este compromisso e acompanhe o progresso.</p></div><button className="close-btn" onClick={() => setSelectedRecord(null)} aria-label="Fechar"><X size={21} /></button></div><div className="modal-content"><div className="detail-status-line"><span className={`status-badge ${statusClass(selectedRecord.status)}`}>{selectedRecord.status}</span>{isOverdue(selectedRecord, today, timeNow) && <span className="status-badge overdue">Publicação atrasada</span>}</div><div className="detail-dates"><div><div className="detail-date-icon blue"><Video size={20} /></div><span>GRAVAÇÃO</span><strong>{formatDate(selectedRecord.recordingDate, { year: "numeric", weekday: "long" })}</strong><small>às {selectedRecord.recordingTime}</small></div><div><div className="detail-date-icon green"><CalendarDays size={20} /></div><span>PUBLICAÇÃO PREVISTA</span><strong>{formatDate(selectedRecord.publicationDate, { year: "numeric", weekday: "long" })}</strong><small>às {selectedRecord.publicationTime}</small></div></div>{selectedRecord.publishedAt && <div className="published-note"><CheckCircle2 size={17} /> Publicado em {new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Asuncion", dateStyle: "short", timeStyle: "short" }).format(new Date(selectedRecord.publishedAt))}</div>}{selectedRecord.notes && <div className="detail-notes"><strong>Observações</strong><p>{selectedRecord.notes}</p></div>}<div className="status-selector"><label htmlFor="status-select">Alterar status</label><div className="select-wrap"><select id="status-select" disabled={busy} value={selectedRecord.status} onChange={e => changeStatus(selectedRecord, e.target.value as Status)}>{statuses.map(s => <option key={s}>{s}</option>)}</select><ChevronDown size={17} /></div></div></div><div className="modal-footer detail-footer"><button className="danger-link" disabled={busy} onClick={() => deleteRecording(selectedRecord)}><Trash2 size={17} /> Excluir</button><div><button className="secondary-btn" onClick={() => openEdit(selectedRecord)}><CalendarDays size={17} /> Remarcar</button><button className="primary-btn" onClick={() => openEdit(selectedRecord)}><Edit3 size={17} /> Editar</button></div></div></div></div>}
    {activeStore && (() => { const storeRecords = records.filter(r => r.storeId === activeStore.id).sort((a,b) => b.recordingDate.localeCompare(a.recordingDate)); const storePayments = payments.filter(p => p.storeId === activeStore.id).sort((a,b) => b.paidOn.localeCompare(a.paidOn)); const info = paymentInfo(activeStore, today); const next = nextPaymentDate(activeStore, today); const hasPayment = !!activeStore.paymentFirstDate || !!activeStore.lastPaymentDate || activeStore.paymentValue !== null; return <div className="modal-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setActiveStore(null); }}><div className="modal detail-modal" role="dialog" aria-modal="true" aria-label="Detalhes da loja"><div className="modal-head"><div><span className="modal-eyebrow">PARCERIA COMERCIAL</span><h2>{activeStore.name}</h2><p>{storeRecords.length} {storeRecords.length === 1 ? "vídeo cadastrado" : "vídeos cadastrados"} nesta loja.</p></div><button className="close-btn" onClick={() => setActiveStore(null)} aria-label="Fechar"><X size={21} /></button></div><div className="store-tabs"><button className={storeTab === "recebimentos" ? "active" : ""} onClick={() => setStoreTab("recebimentos")}><Wallet size={15} /> Recebimentos</button><button className={storeTab === "videos" ? "active" : ""} onClick={() => setStoreTab("videos")}><Video size={15} /> Vídeos ({storeRecords.length})</button></div>{storeTab === "recebimentos" ? <div className="modal-content pay-tab">{hasPayment ? <div className="pay-card">{activeStore.paymentValue !== null && <div className="pay-amount"><span className="pay-label">Valor mensal combinado</span><strong>{formatMoney(activeStore.paymentValue)}</strong></div>}{activeStore.paymentFirstDate && <div className="pay-grid"><div><span>PRIMEIRO RECEBIMENTO</span><strong>{formatDate(activeStore.paymentFirstDate, { year: "numeric", weekday: "long" })}</strong></div><div><span>ÚLTIMO RECEBIDO</span><strong>{activeStore.lastPaymentDate ? formatDate(activeStore.lastPaymentDate, { year: "numeric" }) : "Ainda não registrado"}</strong></div></div>}{next && info && <div className="pay-next"><span>PRÓXIMO RECEBIMENTO</span><strong>{formatDate(next, { year: "numeric", weekday: "long" })}</strong><em className={info.cls}>{info.text}</em></div>}</div> : <div className="empty-state pay-empty"><div className="empty-icon"><Wallet size={23} /></div><strong>Sem recebimento configurado</strong><p>Informe o valor mensal combinado e a data do primeiro recebimento para receber lembretes a cada 30 dias.</p><button onClick={() => openPayModal("edit", activeStore)}><Plus size={15} /> Configurar recebimento</button></div>}<div className="pay-actions"><button className="primary-btn" disabled={busy || !next} onClick={() => openPayModal("register", activeStore)}><Wallet size={17} /> Marcar recebido</button><button className="secondary-btn" onClick={() => openPayModal("edit", activeStore)}><Edit3 size={16} /> Editar valores</button>{activeStore.lastPaymentDate && <button className="danger-link" disabled={busy} onClick={resetCycle}>Reiniciar ciclo</button>}</div>{storePayments.length ? <div className="pay-history"><strong>Últimos recebimentos</strong>{storePayments.slice(0, 5).map(p => <div className="pay-history-row" key={p.id}><span>{formatDate(p.paidOn, { year: "numeric", weekday: "short" })}</span><strong>{formatMoney(Number(p.value))}</strong></div>)}</div> : <div className="pay-history"><strong>Últimos recebimentos</strong><p className="pay-history-empty">Nenhum recebimento registrado ainda.</p></div>}</div> : <div className="modal-content store-history">{storeRecords.length ? storeRecords.map(r => <button key={r.id} className="history-row" onClick={() => { setActiveStore(null); setSelectedRecord(r); }}><span className="event-type-icon recording"><Video size={18} /></span><span><strong>Gravação: {dateTime(r.recordingDate, r.recordingTime)}</strong><small>Publicação: {dateTime(r.publicationDate, r.publicationTime)}</small></span><span className={`status-badge ${statusClass(r.status)}`}>{r.status}</span><ChevronRight size={16} /></button>) : <EmptyState icon={Clapperboard} title="Sem vídeos ainda" text="Crie uma gravação para começar o histórico desta loja." />}</div>}<div className="modal-footer"><button className="secondary-btn" onClick={() => setActiveStore(null)}>Fechar</button><button className="primary-btn" onClick={() => { const name = activeStore.name; openNew(); setForm(f => ({ ...f, storeName: name })); }}><Plus size={17} /> Nova gravação</button></div></div></div>; })()}
    {payModal && <div className="modal-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setPayModal(null); }}><div className="modal small-modal" role="dialog" aria-modal="true" aria-label={payModal.mode === "register" ? "Registrar recebimento" : "Editar recebimento"}><div className="modal-head"><div><span className="modal-eyebrow">RECEBIMENTO · {payModal.shop.name.toUpperCase()}</span><h2>{payModal.mode === "register" ? "Registrar recebimento" : "Editar recebimento"}</h2><p>{payModal.mode === "register" ? "Confirme a data e o valor recebido desta loja. A próxima cobrança sai daqui a 30 dias." : "Ajuste o valor mensal combinado e a data do primeiro recebimento."}</p></div><button className="close-btn" onClick={() => setPayModal(null)} aria-label="Fechar"><X size={21} /></button></div><form onSubmit={savePayModal}><div className="modal-content"><label className="field full"><span>{payModal.mode === "register" ? "Data do recebimento" : "Data do primeiro recebimento"} {payModal.mode === "register" && <b>*</b>}</span><input required={payModal.mode === "register"} type="date" value={payDate} onChange={e => setPayDate(e.target.value)} /></label><label className="field full"><span>{payModal.mode === "register" ? "Valor recebido" : "Valor mensal combinado"} {payModal.mode === "register" && <b>*</b>}</span><input required={payModal.mode === "register"} type="text" inputMode="decimal" placeholder="Ex: 300,00" value={payValue} onChange={e => setPayValue(e.target.value)} /></label>{payError && <div className="inline-error"><AlertCircle size={17} /> {payError}</div>}</div><div className="modal-footer"><button type="button" className="secondary-btn" onClick={() => setPayModal(null)}>Cancelar</button><button className="primary-btn" disabled={busy} type="submit"><Check size={18} /> {busy ? "Salvando..." : payModal.mode === "register" ? "Confirmar recebimento" : "Salvar"}</button></div></form></div></div>}
    {toast && <div className="toast"><CheckCircle2 size={19} /> {toast}<button onClick={() => setToast("")} aria-label="Fechar aviso"><X size={16} /></button></div>}
  </div>;
}
function statusClass(status: Status) { return ({ "Agendada": "scheduled", "Gravada": "recorded", "Em edição": "editing", "Pronta para publicar": "ready", "Publicada": "published", "Cancelada": "cancelled" } as const)[status]; }
function EmptyState({ icon: Icon, title, text, action, onClick }: { icon: typeof Video; title: string; text: string; action?: string; onClick?: () => void }) { return <div className="empty-state"><div className="empty-icon"><Icon size={23} /></div><strong>{title}</strong><p>{text}</p>{action && <button onClick={onClick}><Plus size={15} /> {action}</button>}</div>; }
